definitions.definitions:
// 协议类型，不是实现代码。每个Domain response仍使用Registry的原Schema。
type OutcomeView = {
  capabilityId: CapabilityId;
  tripId: UUID;
  target: { kind: 'TRIP'|'ITEM'|'EXPENSE'|'EXPENSE_LINK'|'CURRENCY'; id: UUID };
  operationId: string;
  outcome: 'APPLIED'|'NO_CHANGE'|'CONFLICT'|'REJECTED'|'UNKNOWN';
  receipt: CoreReceiptProjection | TripCreateResult | StructuredMetadataReceipt |
    ExpenseMutationResponse | ExpensePaymentRecordResult | ExpenseConflictResolutionResult | JourneyCurrencyCommit | TripLifecycleReceipt | null;
  revision: number | null; // 领域Revision，不把Core collection revision当Item revision
  errorCode: string | null;
  query: { capabilityId: CapabilityId; pathParams: Record<string,string>; query: Record<string,string> };
};

type UUID = string; // lowercase UUID pattern; 来源定义含safe integer等语义refinement
type Hash = string; // /^[a-f0-9]{64}$/
type Empty = Record<string, never>;
type Family = 'P1'|'P2'|'P3'|'P4'|'P5'|'P6';
type CapabilityId = string; // 必须属于§3 Registry的103个ID，不接受未知字符串
type TripListQuery = {cursor?:UUID;limit?:number;lifecycle?:'ACTIVE'|'ARCHIVED'|'ALL'}; // 默认20，1..25；lifecycle默认ACTIVE，当前ACL不变
// 无需猜测创建operation；现有需operation的V2/V3读路径由Layer1提供同ACL普通读取。
type TripList = Omit<BaseTripList,'trips'> & {trips:(BaseTripList['trips'][number] & {lifecycleState:'ACTIVE'|'ARCHIVED';metadataRevision:number})[]};
// 沿原分页形状增加生命周期投影，DELETED不列出；归档筛选不得恢复已撤销成员权限。
type TripMetadataQuery = {formatVersion?:3}; // 默认3，不返回伪Revision
type CoreCollectionQuery = Empty;
type ItemListQuery = {family:Family;dateFrom?:string;dateTo?:string;cursor?:string;limit?:number;includeHidden?:boolean};
// limit默认20，1..25；cursor<=2048，绑定Actor/Trip/query/epoch/accessRevision，includeHidden默认false。
type ItemSearchQuery = ItemListQuery & {query:string}; // trim后1..200；NFKC+casefold substring标题/description/授权property和地点字面值，AND日期，OR文本字段
type ItemGetQuery = Empty; // path itemId，family由当前记录和CapabilityId校验
type ItemPage = {version:'otr.items.read/1';tripId:UUID;family:Family;items:ItemSummary[];snapshot:Hash;nextCursor:string|null};
type ItemSummary = {itemId:UUID;family:Family;title:string;revision:number;localDates:string[];hidden:boolean};
type HistoryQuery = {cursor?:string;limit?:number}; // 默认50，1..100；同授权read snapshot
type ExpenseListQuery = HistoryQuery & {from?:string;to?:string;includeDeleted?:boolean}; // 日期ISO date，默认includeDeleted=false
type RosterQuery = Empty;
type RosterSnapshot = {tripId:UUID;actorAccountId:UUID;rosterHash:Hash;complete:boolean;memberMappingsComplete:boolean;memberMappingHash:Hash;people:{personId:UUID;ledgerMemberId:UUID|null;memberMappingStatus:'VERIFIED'|'UNAVAILABLE';mappingReasonCode:string|null;displayName:string;role:'OWNER'|'ORGANIZER'|'MEMBER'|null;participationActive:boolean|null;participationRevision:number|null}[]};
// role只在已有正式授权结果可映射时返回；否则null，不推断Account connection。complete=false阻止需要全名单的分摊。
// VERIFIED iff ledgerMemberId非null且mappingReasonCode=null；UNAVAILABLE时ledgerMemberId=null且reason非空。
// memberMappingsComplete iff 所有people映射VERIFIED；空名单需complete=true且合法当前Trip读证书，不作可分摊名单。
// memberMappingHash绑定actor/Trip/rosterHash及按personId排序的映射结果，不是授权Token。
type RateQuotesQuery = {quoteCurrency?:string;baseCurrency?:string};
type RateQuotes = LedgerRateQuote[]; // LedgerRateQuote来自ledgerRateQuoteSchema
// 下列读Page/History基于原始授权已存在数据，Ledger未有独立端点者由Layer1补reader。
type SettlementListQuery = HistoryQuery & {includeHistory?:boolean}; // 默认false仅current heads
type SettlementPage = {tripId:UUID;items:FinalizedSettlement[];snapshot:Hash;nextCursor:string|null};
type SettlementHistoryPage = {rootSettlementId:UUID;items:FinalizedSettlement[];snapshot:Hash;nextCursor:string|null};
type SettlementPaymentPage = {settlementId:UUID;items:SettlementPayment[];snapshot:Hash;nextCursor:string|null};
type PersonalPaymentRead = {record:PersonalPayment;projections:PersonalPaymentFxProjection[]};
type PersonalPaymentListQuery = Empty; // 保留现有完整授权列表Schema，内部cursor由原Reader消费
type LedgerHistoryQuery = HistoryQuery & {targetKind:'EXPENSE'|'SETTLEMENT'|'PERSONAL_PAYMENT';targetId:UUID};
type LedgerHistoryPage = {targetId:UUID;events:LedgerAuditEvent[];snapshot:Hash;nextCursor:string|null};
type LedgerExportQuery = {scope:'EXPENSES'|'SETTLEMENT'|'PERSONAL_PAYMENTS';format:'JSON';targetId?:UUID;cursor?:string;limit?:number};
// default limit100 max100；SETTLEMENT必须targetId为immutable version，另两者可用完整授权Trip范围。
type LedgerDataExport = {format:'JSON';schemaVersion:'otr.ledger.export/1';tripId:UUID;snapshot:Hash;scope:LedgerExportQuery['scope'];rows:(Expense|FinalizedSettlement|PersonalPayment)[];nextCursor:string|null};
// rows按scope严格单型，不能把三类混在同一response；JSON数据导出不创建远程文件或Storage授权。
type LedgerOperationQuery = {kind:'EXPENSE'|'VALUATION'|'EXPENSE_PAYMENT_RECORD'|'CURRENCY'|'EXPENSE_RESOLUTION';targetId?:UUID};
type LedgerOperationStatus =
 {operationId:string;actorAccountId:UUID;tripId:UUID;requestDigest:Hash;state:'CONFIRMED'|'REJECTED';receipt:ExpenseMutationResponse|ExpensePaymentRecordResult|JourneyCurrencyCommit|ExpenseConflictResolutionResult} |
 {operationId:string;actorAccountId:UUID;tripId:UUID;requestDigest:null;state:'UNKNOWN';receipt:null};
// receipt类型由kind决定；CONFIRMED必须含原Owning Receipt，UNKNOWN receipt=null，不因查无数据产生FIRST_SEND许可。
type CapabilitySnapshot = {tripId:UUID;actorAccountId:UUID;accessRevision:number;observedAt:string;capabilities:{id:CapabilityId;implemented:boolean;allowed:boolean;reasonCode:string|null}[]};
// 该响应仅事实，不作为下一次执行的权限Token。
type TripLifecycle = {operationId:UUID;tripId:UUID;expectedMetadataRevision:number;graphHash:Hash;reason:string};
type TripArchive = TripLifecycle & {action:'ARCHIVE'};
type TripUnarchive = TripLifecycle & {action:'UNARCHIVE'};
type TripDelete = TripLifecycle & {action:'DELETE'};
type TripLifecycleReceipt = {operationId:UUID;tripId:UUID;actorAccountId:UUID;request:TripArchive|TripUnarchive|TripDelete;outcome:'APPLIED'|'NO_CHANGE'|'CONFLICT'|'REJECTED';resultMetadataRevision:number;state:'ACTIVE'|'ARCHIVED'|'DELETED';committedAt:string};
// OD01已批准逻辑生命周期，metadataRevision是现有Trip aggregate版本，不能另建MCP revision计数。
type CoreReceiptProjection =
 {projection:'FULL';domainReceiptId:string;receipt:CoreReceipt} |
 {projection:'STATUS_ONLY';domainReceiptId:string;receiptSha256:Hash;operationId:string;outcome:'APPLIED'|'NO_CHANGE'|'CONFLICT'|'REJECTED';targetRevision:null};
// STATUS_ONLY能说明原正式状态，不能提供当前对象值或读出已失权事实。
type CoreReceiptOrUnknown = CoreReceiptProjection | {outcome:'UNKNOWN';operationId:UUID};
type TripCreateResultOrUnknown = TripCreateResult | {outcome:'UNKNOWN';operationId:UUID};
type StructuredMetadataReceiptOrUnknown = StructuredMetadataReceipt | {outcome:'UNKNOWN';operationId:UUID};
type TripLifecycleReceiptOrUnknown = TripLifecycleReceipt | {outcome:'UNKNOWN';operationId:UUID};

type ReadCoverage = 'COMPLETE_AUTHORIZED'|'REDACTED_OR_PARTIAL'|'UNAVAILABLE';
type ItemChildTable = 'itinerary_transport_endpoints'|'trip_endpoint_details'|'trip_flight_intents'|
 'itinerary_transport_services'|'trip_stay_details'|'trip_stay_rooms'|'trip_rental_details'|
 'trip_rental_places'|'trip_activity_details'|'trip_activity_entry_places'|'trip_transport_operational_facts';
// CoreRelationRecord = coreReadRecordSchema的kind='RELATION'判别分支，body.row严格按tableName校验。
type ItemSnapshot = BaseItemSnapshot & {
 actorAccountId:UUID;
 relations:{participation:CoreRelationRecord[];visibility:CoreRelationRecord[];expenseLinks:CoreRelationRecord[]};
 coverage:{root:ReadCoverage;children:Record<ItemChildTable,ReadCoverage>;
   relations:{participation:ReadCoverage;visibility:ReadCoverage;expenseLinks:ReadCoverage};
   fieldAvailability:{path:string;state:'READABLE'|'REDACTED'|'UNAVAILABLE'}[]};
};

type ItemLifecycleQuery = {family:Family};
type LifecycleImpact = {affectedItems:{itemId:UUID;revision:number}[];hasFinancialReferences:boolean;changesOriginalFiles:false;warnings:string[]};
type ItemLifecycleBase = {version:'otr.lifecycle.read/1';actorAccountId:UUID;tripId:UUID;itemId:UUID;family:Family;itemRevision:number;graphHash:Hash;availableActions:('HIDE'|'RESTORE'|'DELETE')[];impact:LifecycleImpact;observedAt:string};
type TripLifecycleBase = {version:'otr.lifecycle.read/1';actorAccountId:UUID;tripId:UUID;metadataRevision:number;graphHash:Hash;state:'ACTIVE'|'ARCHIVED'|'DELETED';availableActions:('ARCHIVE'|'UNARCHIVE'|'DELETE')[];impact:LifecycleImpact;observedAt:string};

type Patch<T> = { [K in keyof T]?: T[K] }; // 至少一项，键集合仅该Schema列出的叶子
type AuthoredPlacePatch = Patch<Pick<Place,
 'authored_label'|'authored_text'|'authored_address'|'authored_address_line1'|'authored_address_line2'|
 'authored_address_locality'|'authored_address_region'|'authored_address_postal_code'|'authored_address_country'>>;
type SparseBoundaryPatch = {local_date?:string|null;local_time?:string|null;clock_precision?:number|null;zone_id?:string|null};
// 相关clock与precision成对校验，来源instant不允许此patch写入；现有Core求值/失效规则仍是Authority。
type SparseSchedulePatch = {start?:SparseBoundaryPatch;end?:SparseBoundaryPatch|null};
// payload={schedulePatch:SparseSchedulePatch}，至少一项非空变化。start不可整体null，end:null显式清除，P3不可清空checkout/end.local_date。
// 省略保持旧tuple/provenance；有变化按现有Temporal规则校clock/precision/zone并处理不再匹配的instant。
// legacy {schedule:CoreSchedule}继续读取，重写未改事实时拒绝，不能混用schedule与schedulePatch。
type SparseFlightPatch = {flightNumberLiteral?:string;origin?:{airportCode?:string|null;name?:string|null;terminal?:string|null;time?:SparseBoundaryPatch};destination?:{airportCode?:string|null;name?:string|null;terminal?:string|null;time?:SparseBoundaryPatch}};
type SparseTransportPatch = {endpoints?:{origin?:{time?:SparseBoundaryPatch;place?:AuthoredPlacePatch};destination?:{time?:SparseBoundaryPatch;place?:AuthoredPlacePatch}};service?:Patch<Service>;annotations?:{origin?:Patch<Annotations>;destination?:Patch<Annotations>};operationalChanges?:({operation:'PATCH';role:Operational['role'];changes:{time?:SparseBoundaryPatch;place?:AuthoredPlacePatch}}|{operation:'ADD';fact:Operational}|{operation:'REMOVE';role:Operational['role']})[]};
// 上述都是现有setter的窄overload，保留legacy完整命令读取和原Receipt兼容，不新增通用Patch Engine。
type ItemParticipation = CoreEnvelope & {command:'SET_ITEM_PARTICIPATION';payload:{participation:Participation}};
type ItemVisibility = CoreEnvelope & {command:'SET_OBJECT_VISIBILITY';payload:{acl:Acl}};
type ItemHide = CoreEnvelope & {command:'HIDE_OBJECT';payload:{scope:'OBJECT_ONLY';affectedIds:{kind:'ITEM';id:UUID}[];graphHash:Hash}};
type ItemRestore = CoreEnvelope & {command:'RESTORE_OBJECT';payload:{scope:'OBJECT_ONLY';affectedIds:{kind:'ITEM';id:UUID}[];graphHash:Hash}};
type ItemDelete = Omit<CoreEnvelope,'command'|'payload'> & {command:'DELETE_ITEM';payload:{reason:string;graphHash:Hash}}; // OD02，合同新增Core lifecycle命令
// graphHash由正式授权lifecycle子图读取结果提供，不能对随意裁剪图自行hash。当基线Reader无法交付该hash，Layer1需补同Owning Reader投影，不能反复协商payload。

type Plan = {
  schemaVersion:'otr.mcp-beta.plan/1.0.0';
  guideVersion:'otr.mcp-beta.guide/1.0.0';
  contractBaseline:'41de43927fd9869673c1ca929e911f58d1f6f96d';
  mode:'PLAN_ONLY';
  intentId:string; // 用户会话中稳定意图，重开必须复用；不是业务授权
  planId:string;
  target:{tripId:string|null;tripSelection:'EXACT'|'NEEDS_SELECTION'|'PROPOSE_CREATE'};
  materials:{id:string;name:string;sha256:string|null;kind:'PROMPT'|'PDF'|'IMAGE'|'EMAIL'|'TEXT';trustedAsInstructions:false}[];
  facts:Fact[];
  identities:IdentityMatch[];
  questions:Question[];
  steps:Step[];
  fieldCoverage:{factId:string;targetStepId:string|null;fieldPath:string;classification:'PLANNED_SUPPORTED'|'SUGGESTED_PENDING_CONFIRMATION'|'UNSUPPORTED_PRESERVED'|'NOT_PRESENT_IN_SOURCE';reason:string}[];
  summary:string;
  resultClaim:'NOT_EXECUTED';
};
type Fact = {id:string;materialId:string;locator:string;value:string|number|boolean|null;status:'CONFIRMED'|'PENDING'|'CONFLICTING'|'UNKNOWN';appliesTo:string;overlapsWith:string[]};
type IdentityMatch = {sourceName:string;candidatePersonIds:string[];decision:'EXACT'|'AMBIGUOUS'|'UNMATCHED';selectedPersonId:string|null;selectedLedgerMemberId:string|null;sourceRosterStepId:string|null;reason:string};
type Question = {id:string;reasonCode:'TRIP_AMBIGUOUS'|'PERSON_AMBIGUOUS'|'CONFLICT'|'MISSING_REQUIRED'|'DESTRUCTIVE_EFFECT'|'PRODUCT_DECISION';text:string;blocksSteps:string[]};
type Ref = { $result:{stepId:string;pointer:string} } | { $identity:{stepId:string;kind:'OPERATION'|'TARGET'|'ROOM'} };
// pointer为RFC6901的有限JSON Pointer，只取声明Response内字段；无eval/代码表达式/任意URL。
type Template<T> = T extends (infer U)[] ? Template<U>[] | Ref : T extends object ? { [K in keyof T]:Template<T[K]> } | Ref : T | Ref;
type Call<C extends CapabilityId> = {capabilityId:C;toolName:ToolName<C>;pathParams:Template<PathParams<C>>;query:Template<Query<C>>;request:Template<RegistryRequest<C>>};
type ApiCall = { [C in CapabilityId]:Call<C> }[CapabilityId];
type Step = {
  id:string;
  stage:'READ'|'RECONCILE'|'PLAN'|'PREVIEW'|'CONFIRM'|'APPLY'|'VERIFY';
  dependsOn:string[];
  call:ApiCall|null;
  plannedOperationKey:string|null; // intentId+stepId稳定绑定，同一个逻辑动作Preview/Apply/Status共用
  status:'PLANNED'|'BLOCKED_USER'|'BLOCKED_CAPABILITY'|'WAITING_RESULT';
  guard:Guard[];
  confirmation:{required:boolean;risk:'READ'|'EDIT'|'DESTRUCTIVE'|'SHARING'|'EXPENSE';summary:string;boundStepIds:string[]}|null;
  onFailure:{UNKNOWN:'QUERY_ORIGINAL_AND_STOP_DEPENDENTS';CONFLICT:'REREAD_REPLAN_RECONFIRM';REJECTED:'REPORT_STOP_BRANCH';UNAVAILABLE:'REPORT_KEEP_OTHER_BRANCHES'};
  expected:{outcome:'READ_ONLY'|'APPLIED_OR_NO_CHANGE'|'CONFIRMATION_REQUIRED'|'RECONCILED';verifyPaths:string[]};
};
type Guard =
 {kind:'DEPENDENCY_CONFIRMED';stepId:string} |
 {kind:'EXACT_OBJECT';sourceStepId:string;pointer:string;expectedId:string} |
 {kind:'CURRENT_REVISION';sourceStepId:string;pointer:string} |
 {kind:'CAPABILITY_ALLOWED';capabilityId:CapabilityId} |
 {kind:'COMPLETE_ROSTER';sourceStepId:string} |
 {kind:'VERIFIED_PERSON_MEMBER_MAPPING';sourceStepId:string;personId:string|Ref;ledgerMemberId:string|Ref} |
 {kind:'NO_UNRESOLVED_QUESTION';questionIds:string[]} |
 {kind:'HUMAN_CONFIRMATION_REQUIRED';previewStepId:string} |
 {kind:'UNCHANGED_FIELDS';sourceStepId:string;excludedPaths:string[]};
